"use strict";(globalThis.webpackChunkztools_docs=globalThis.webpackChunkztools_docs||[]).push([[50333],{95382(o){o.exports=JSON.parse('{"id":"empora","name":"Empora","url":"https://empora.aoneahsan.com","platforms":["WordPress plugin"],"logo":"/ecosystem/empora.svg","card":"One WordPress plugin for store features, the way ZTools is one site for tools.","title":"Empora: one plugin in place of a stack of WooCommerce plugins","intro":"Empora puts WooCommerce store modules into one WordPress plugin. You switch on only the modules your store needs.","sections":[["Why would ZTools mention a store plugin?","ZTools exists because a separate website for every small tool is hard to keep track of. Empora applies the same idea to a WooCommerce store: one plugin to manage, not a separate one for each feature."],["Do I have to use every module?","No. You choose which modules to switch on."],["Where do I manage licenses?","In the Empora web dashboard, which also handles optional store connections."]]}')}}]);